"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96886"],{69496(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.derivacao_da_oferta","status":422,"titulo":"O fato \xe9 derivado das modalidades que o processo oferta e n\xe3o se configura no processo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.derivacao_da_oferta","requisitos":["UNI-REQ-0076"],"oQueAconteceu":["O pedido tentou configurar, no processo, uma regra de deriva\xe7\xe3o para um fato que o\\npr\xf3prio sistema deriva das modalidades que o processo oferta: a modalidade de\\nconcorr\xeancia da pessoa candidata (`MODALIDADE`) ou a op\xe7\xe3o pelas cotas da lei\\n(`OPTOU_PELAS_COTAS_DA_LEI`). Esses fatos saem da distribui\xe7\xe3o de vagas e das regras de\\ncada modalidade ofertada; uma segunda regra, no processo, criaria uma defini\xe7\xe3o\\nconcorrente. A recusa sai com **422**, no campo `configuracoes[i].codigoFato` da\\nconfigura\xe7\xe3o que cita o fato, e nada foi gravado."],"comoResolver":["Retire do pedido a configura\xe7\xe3o desse fato e reenvie as demais regras de deriva\xe7\xe3o\\n(`PUT /api/selecao/processos-seletivos/{id}/regras-derivacao`). Para mudar quem concorre\\na cada modalidade, ajuste a distribui\xe7\xe3o de vagas e a regra de aplicabilidade das\\nmodalidades ofertadas\\n(`PUT /api/selecao/processos-seletivos/{id}/distribuicao-vagas`), e n\xe3o uma regra de\\nderiva\xe7\xe3o \xe0 parte."],"ondeAparece":["Defini\xe7\xe3o de regras de deriva\xe7\xe3o de fatos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);